source='''from collections import Counter, defaultdict
from math import hypot

def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for q in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    yy, xx = q
                    if 0 <= yy < h and 0 <= xx < w and q not in seen and grid[yy][xx] == color:
                        seen.add(q)
                        stack.append(q)
            out.append((color, cells))
    return out

def _shape(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    return frozenset((r-r0, c-c0) for r, c in cells)

def _is_reference_l(cells):
    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    h, w = r1-r0+1, c1-c0+1
    if h < 3 or w < 3:
        return False
    for rr in (r0, r1):
        for cc in (c0, c1):
            expected = {(rr, x) for x in range(c0,c1+1)} | {(y, cc) for y in range(r0,r1+1)}
            if cells == expected:
                return True
    return False

def transform(grid):
    grid = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, background)
    refs = [(color, cells) for color, cells in comps if _is_reference_l(cells)]
    if not refs:
        return grid
    ref_color, ref_cells = max(refs, key=lambda item: len(item[1]))
    ref_center = (sum(r for r,c in ref_cells)/len(ref_cells), sum(c for r,c in ref_cells)/len(ref_cells))
    groups = defaultdict(list)
    for color, cells in comps:
        if cells != ref_cells:
            groups[_shape(cells)].append((color, cells))
    candidates = []
    for group in groups.values():
        if len(group) < 2:
            continue
        # The matching object farthest from the L-shaped color marker is the one to recolor.
        distinct_colors = {color for color, cells in group}
        if len(distinct_colors) < 2:
            continue
        for color, cells in group:
            center = (sum(r for r,c in cells)/len(cells), sum(c for r,c in cells)/len(cells))
            distance = hypot(center[0]-ref_center[0], center[1]-ref_center[1])
            candidates.append((distance, color, cells))
    if candidates:
        _, _, target = max(candidates, key=lambda item: item[0])
        for r, c in target:
            grid[r][c] = ref_color
    return grid
